#' Select priority species for restoration
#'
#' Selects plant species according to their cumulative contribution to the
#' Interaction-based Restoration Priority Index (IPR).
#'
#' Species are ranked from highest to lowest IPR, and their cumulative
#' contribution is calculated to identify the minimum set of species
#' required to achieve a user-defined restoration priority threshold.
#'
#' @param prioritization A data frame generated by
#' \code{calculate_IPR()}, containing at least the column \code{IPR}.
#'
#' @param threshold Numeric value between 0 and 1 representing the desired
#' cumulative proportion of total IPR to retain. Default is 0.80.
#'
#' @return A data frame containing the selected priority species and two
#' additional columns:
#' \itemize{
#'   \item \code{relative_IPR}: proportional contribution of each species.
#'   \item \code{cumulative_IPR}: cumulative contribution to total IPR.
#' }
#'
#' @details
#' Species are ordered in decreasing IPR values.
#'
#' The proportional contribution of each species is calculated as:
#'
#' \deqn{
#' relative\_IPR_i = \frac{IPR_i}{\sum IPR}
#' }
#'
#' and the cumulative contribution as:
#'
#' \deqn{
#' cumulative\_IPR_i = \sum_{j=1}^{i} relative\_IPR_j
#' }
#'
#' The function returns the minimum set of species whose cumulative
#' contribution reaches or exceeds the specified threshold.
#'
#' This procedure is analogous to identifying the smallest group of species
#' responsible for a target proportion of the overall restoration priority.
#'
#' @examples
#' data <- data.frame(
#'   plant_species = c("A", "A", "B", "C", "C", "D"),
#'   bee_species = c("b1", "b2", "b1", "b2", "b3", "b1"),
#'   sample_unit = c("S1", "S1", "S2", "S2", "S3", "S3")
#' )
#'
#' result <- restaurabee(data)
#'
#' selected <- select_species(
#'   result$prioritization,
#'   threshold = 0.80
#' )
#'
#' @export
select_species <- function(
    prioritization,
    threshold = 0.80
) {

  if (threshold <= 0 || threshold > 1) {
    stop(
      "'threshold' must be greater than 0 and less than or equal to 1.",
      call. = FALSE
    )
  }

  if (!is.data.frame(prioritization)) {
    stop(
      "'prioritization' must be a data frame.",
      call. = FALSE
    )
  }

  if (!"IPR" %in% names(prioritization)) {
    stop(
      "'prioritization' must contain an 'IPR' column.",
      call. = FALSE
    )
  }

  if (nrow(prioritization) == 0) {
    stop(
      "'prioritization' must contain at least one row.",
      call. = FALSE
    )
  }

  if (anyNA(prioritization$IPR)) {
    stop(
      "'IPR' must not contain missing values.",
      call. = FALSE
    )
  }

  total_IPR <- sum(prioritization$IPR)

  if (!is.finite(total_IPR) || total_IPR <= 0) {
    stop(
      "The sum of 'IPR' values must be greater than zero.",
      call. = FALSE
    )
  }

  result <-
    prioritization |>
    dplyr::arrange(
      dplyr::desc(IPR)
    ) |>
    dplyr::mutate(
      relative_IPR = IPR / total_IPR,
      cumulative_IPR = cumsum(relative_IPR)
    )

  last_species <-
    which(result$cumulative_IPR >= threshold)[1]

  result |>
    dplyr::slice(
      seq_len(last_species)
    )
}
